function science(){return `<section class="science" id="science">${picture('photons',t('Artistic microscopic visualization of red light and translucent cell-like forms','Visualización artística microscópica de luz roja y formas celulares translúcidas'),'science-bg')}<i class="photon"></i><i class="photon two"></i><i class="photon three"></i><div class="wrap"><div class="science-top"><span class="eyebrow">${t('Behind the glow','Detrás de la luz')}</span><h2>${t('Where the light<br><em>comes from.</em>','De dónde<br><em>sale la luz.</em>')}</h2><p>${t('Every LED inside LEZO turns electricity into one precise color. Three channels, red, green and blue, blend into the seven modes you can pick.','Cada LED dentro de LEZO convierte la electricidad en un color preciso. Tres canales, rojo, verde y azul, se mezclan en los siete modos que puedes elegir.')}</p></div><div class="science-bottom"><article><span class="eyebrow">01 / ${t('Emission','Emisión')}</span><h3>${t('Three channels. Seven modes.','Tres canales. Siete modos.')}</h3><p>${t('Red (630 nm), green (520 nm) and blue (470 nm) combine into purple, yellow, cyan and white, so one mask covers the whole palette.','Rojo (630 nm), verde (520 nm) y azul (470 nm) se combinan en morado, amarillo, cian y blanco: una sola máscara cubre toda la paleta.')}</p><div class="energy-detail"><span class="energy-line" aria-hidden="true"></span><span>${t('Energy transition → photon','Transición de energía → fotón')}</span></div></article><article><span class="eyebrow">02 / ${t('Wavelength','Longitud de onda')}</span><h3>${t('Every color has its own job.','Cada color tiene su función.')}</h3><p>${t('The supplier describes a different purpose for each mode. Pick a color in the viewer at the top of the page and read them one by one.','El proveedor describe una función distinta para cada modo. Elige un color en el visor de la parte superior y léelas una por una.')}</p></article><article><span class="eyebrow">03 / ${t('Interaction','Interacción')}</span><h3>${t('Hands-free by design.','Manos libres por diseño.')}</h3><p>${t('A full-face shell, an adjustable strap and a mode for every mood. Put it on, pick your light and keep your hands free.','Un diseño de rostro completo, correa ajustable y un modo para cada ánimo. Póntela, elige tu luz y deja las manos libres.')}</p></article></div><div class="science-note">${t('Artistic visualization, not to scale. General explanation of light; not a clinical demonstration of this product.','Visualización artística, no a escala. Explicación general de la luz; no es una demostración clínica del producto.')}</div></div></section>`}
