function results(){return `<section class="results"><div class="results-grid"><div class="results-photo">${picture('portrait',t('Editorial portrait of a woman with natural skin texture holding the mask','Retrato editorial de una mujer con textura natural en la piel sosteniendo la máscara'))}</div><div class="results-copy"><span class="eyebrow">${t('Straight talk','Hablemos claro')}</span><h2>${t('Good skin days.<br>Start with<br><em>good habits.</em>','Los buenos días<br>de tu piel.<br><em>Empiezan en ti.</em>')}</h2><p>${t('We will not promise miracles. We will give you a well-made mask, seven light modes and a routine you will actually look forward to. Results vary from person to person, and research on other devices does not prove results for this mask.','No prometemos milagros. Te damos una máscara bien hecha, siete modos de luz y una rutina que sí vas a querer hacer. Los resultados varían en cada persona y los estudios de otros equipos no prueban resultados de esta máscara.')}</p><div class="result-points"><div><span>01</span>${t('Consistency beats quick fixes.','La constancia le gana a las soluciones rápidas.')}</div><div><span>02</span>${t('A complement to the products you already use.','Un complemento a los productos que ya usas.')}</div><div><span>03</span>${t('Every skin responds differently.','Cada piel responde distinto.')}</div></div><p class="small">${t('Model imagery is illustrative, not a customer result or before-and-after. No clinical outcome data has been supplied for this product.','La imagen de la modelo es ilustrativa, no un resultado de cliente ni un antes y después. No se han aportado datos clínicos de este producto.')}</p><a class="source-link" href="https://www.aad.org/public/cosmetic/safety/red-light-therapy" target="_blank" rel="noopener noreferrer">${t('Read the American Academy of Dermatology’s guidance ↗','Leer la guía de la Academia Estadounidense de Dermatología ↗')}</a></div></div></section>`}
function faq(){const items=[
[t('What does each of the 7 colors do?','¿Para qué sirve cada uno de los 7 colores?'),t('Red, green, blue, purple, yellow, cyan and white. The supplier lists 630 nm red, 520 nm green and 470 nm blue; the other modes combine those channels. These values have not been independently verified.','Rojo, verde, azul, morado, amarillo, cian y blanco. El proveedor indica 630 nm para rojo, 520 nm para verde y 470 nm para azul; el resto combina esos canales. No se han verificado de forma independiente.')],
[t('How long should each session last?','¿Cuánto debe durar cada sesión?'),t('Use the session duration, frequency and eye protection specified in the instructions supplied with your device. We do not prescribe a universal session length. Do not exceed the manufacturer’s directions.','Usa la duración, frecuencia y protección ocular indicadas en las instrucciones de tu equipo. No prescribimos una duración universal. No excedas las indicaciones del fabricante.')],
[t('What results can I expect?','¿Qué resultados puedo esperar?'),t('Responses to LED skincare vary with the device, dose, consistency and your skin. We have not received clinical trial results for this model, so we do not promise a specific change or timeframe. This mask is not presented as a cure for acne, scars or other medical conditions.','Las respuestas varían según dispositivo, dosis, constancia y piel. No recibimos ensayos clínicos de este modelo, por lo que no prometemos un cambio o plazo específico. No se presenta como cura para acné, cicatrices u otras enfermedades.')],
[t('Is it suitable for everyone?','¿Es adecuada para todas las personas?'),t('Check with a dermatologist if you have a light-sensitive condition, take photosensitizing medication, or have concerns about your skin or eyes. Follow the eye-protection instructions. Stop use if irritation occurs. No FDA clearance claim is made for this model.','Consulta con dermatología si tienes sensibilidad a la luz, tomas medicamentos fotosensibilizantes o tienes dudas sobre tu piel u ojos. Sigue las instrucciones de protección ocular. Suspende el uso si hay irritación. No afirmamos autorización FDA para este modelo.')],
[t('How does the 45% offer work?','¿Cómo funciona el 45% de descuento?'),t('The regular price is $119. The LEZO45 code reduces it by $53.55 to $65.45 before shipping and tax. The code is added to checkout from this page and expires October 31, 2026 at 4:31 p.m. Eastern Time. It applies to this mask for all customers during the promotion.','El precio regular es $119. El código LEZO45 resta $53.55 y lo deja en $65.45 antes de envío e impuestos. Se añade al checkout desde esta página y vence el 31 de octubre de 2026 a las 4:31 p. m., hora del este. Aplica a esta máscara para todos los clientes durante la promoción.')],
[t('What if I change my mind?','¿Y si me arrepiento?'),t('Yes. Request a return within 30 days of delivery by emailing sevencrush.store@gmail.com with your order number. Contact us before sending anything back so we can provide the return address and instructions. See the full return details below.','Sí. Solicita la devolución dentro de los 30 días desde la entrega escribiendo a sevencrush.store@gmail.com con tu número de pedido. Contáctanos antes de enviarla para recibir la dirección e instrucciones. Consulta los detalles de devolución al pie de la página.')],
[t('How fast does it arrive, and how do I pay?','¿Cuánto tarda en llegar y cómo pago?'),t('Estimated delivery is 5–12 days. Pay through Sevencrush’s secure Shopify checkout, where shipping charges, taxes and available payment methods are shown before you confirm. Order updates arrive at the email used at checkout.','La entrega estimada es de 5 a 12 días. Paga en el checkout seguro de Shopify de Sevencrush: verás gastos de envío, impuestos y métodos disponibles antes de confirmar. Recibirás las actualizaciones en el correo de tu pedido.')]
];return `<section class="wrap section faq-grid" id="questions"><div><span class="eyebrow">${t('Product & order details','Producto y pedido')}</span><h2>${t('Before you<br>switch on.','Antes de<br>encenderla.')}</h2><p>${t('Use, delivery and returns.<br>The details to know before ordering.','Uso, entrega y devoluciones.<br>Los detalles antes de comprar.')}</p><a class="text-link" href="mailto:${CONFIG.email}">${t('Talk to Sevencrush','Habla con Sevencrush')} ${icon('arrow')}</a></div><div class="faq-list">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>`}
function footer(){return `<div class="wrap"><div class="service-band"><div>${icon('return')}<h3>${t('30 days to change your mind.','30 días para arrepentirte.')}</h3><p>${t('Request your return within 30 days of delivery.','Solicita tu devolución dentro de los 30 días desde la entrega.')}</p></div><div>${icon('shield')}<h3>${t('Secure payment.','Pago seguro.')}</h3><p>${t('Your payment is handled through Sevencrush’s Shopify checkout.','Tu pago se procesa en el checkout de Shopify de Sevencrush.')}</p></div><div>${icon('mail')}<h3>${t('Order support.','Ayuda con tu pedido.')}</h3><p><a href="mailto:${CONFIG.email}">${CONFIG.email}</a></p></div></div></div><footer><div class="wrap"><div class="footer-top"><div><a href="/" class="footer-brand">LEZO</a><div class="footer-tagline">${t('LED face mask by Sevencrush.','Máscara LED facial por Sevencrush.')}</div></div><div class="footer-links"><div><h3>${t('Explore','Explora')}</h3><a href="/products/lezo-7-color-led-face-mask">${t('The LED mask','La máscara LED')}</a><a href="${location.pathname.includes('/products/')?'#mask3d':'/#mask3d'}">${t('The seven modes','Los siete modos')}</a><a href="/#ritual">${t('Use guide','Guía de uso')}</a><a href="/#questions">FAQ</a></div><div><h3>${t('Customer care','Atención al cliente')}</h3><a href="/pages/lezo-returns/">${t('Returns','Devoluciones')}</a><a href="/pages/lezo-delivery/">${t('Shipping','Envíos')}</a><button data-policy="privacy">${t('Privacy','Privacidad')}</button><button data-policy="terms">${t('Terms','Términos')}</button><a href="mailto:${CONFIG.email}">${t('Contact us','Contáctanos')}</a></div></div></div><div class="footer-bottom"><span>LEZO BY SEVENCRUSH · ${t('UNITED STATES / USD','ESTADOS UNIDOS / USD')}</span><span>${t('Original editorial imagery. Product visualizations may vary from the delivered item.','Imágenes editoriales originales. Las visualizaciones pueden variar del artículo entregado.')}</span></div></div></footer>`}
function skinComparison(){return `<section class="skin-study wrap section" id="skin-study"><div class="section-head"><div><span class="eyebrow">${t('The skin study / 01','Estudio de la piel / 01')}</span><h2>${t('Texture.<br>In a new dimension.','La textura.<br>En otra dimensión.')}</h2></div><div class="study-intro"><span class="concept-tag">${t('3D CONCEPT · NOT PRODUCT RESULTS','CONCEPTO 3D · NO SON RESULTADOS DEL PRODUCTO')}</span><p>${t('Slide between two illustrated skin states: a more uneven surface and a smoother-looking surface.','Desliza entre dos estados ilustrados de la piel: una superficie más irregular y otra de aspecto más uniforme.')}</p></div></div><div class="skin-comparison" style="--split:50%"><div class="compare-images">${picture('skin-after',t('Conceptual 3D illustration of a smoother skin-like surface','Ilustración conceptual 3D de una superficie de aspecto más uniforme'),'comparison-after')}<div class="comparison-before">${picture('skin-before',t('Conceptual 3D illustration of a more uneven skin-like surface','Ilustración conceptual 3D de una superficie de aspecto más irregular'))}</div><div class="compare-label before">${t('BEFORE','ANTES')}<small>${t('Concept','Concepto')}</small></div><div class="compare-label after">${t('AFTER','DESPUÉS')}<small>${t('Concept','Concepto')}</small></div><div class="comparison-line" aria-hidden="true"><span>‹ &nbsp; ›</span></div><input type="range" min="0" max="100" value="50" step="1" data-compare aria-label="${t('Slide to compare the conceptual before and after skin illustrations','Desliza para comparar las ilustraciones conceptuales de piel antes y después')}" aria-valuetext="50%"></div><div class="compare-controls"><span>${t('More uneven texture','Textura más irregular')}</span><span class="drag-hint">↔ ${t('DRAG TO EXPLORE','DESLIZA PARA EXPLORAR')}</span><span>${t('More even-looking texture','Textura de aspecto más uniforme')}</span></div></div><p class="study-disclosure">${t('Artistic before-and-after concept, not a treatment sequence. These images do not show measured effects of LEZO, a customer result, or a promised outcome.','Concepto artístico de antes y después, no una secuencia de tratamiento. Estas imágenes no muestran efectos medidos de LEZO, resultados de clientes ni un resultado prometido.')}</p></section>`}
function skinLayers(){return `<section class="skin-depth"><div class="wrap section"><div class="depth-heading"><span class="eyebrow">${t('The skin study / 02','Estudio de la piel / 02')}</span><h2>${t('Look beneath<br><em>the surface.</em>','Mira debajo<br><em>de la superficie.</em>')}</h2><p>${t('A second perspective on texture and structure.<br>An artistic cutaway makes the contrast visible.','Otra perspectiva de textura y estructura.<br>Un corte artístico hace visible el contraste.')}</p><span class="concept-tag">${t('ILLUSTRATIVE SKIN STATES · NOT CLINICAL EVIDENCE','ESTADOS ILUSTRATIVOS · NO SON EVIDENCIA CLÍNICA')}</span></div><div class="depth-image">${picture('skin-layers',t('Two artistic 3D skin-inspired cutaway blocks comparing uneven and even surface concepts','Dos bloques artísticos en corte 3D comparando conceptos de superficie irregular y uniforme'))}</div><div class="depth-captions"><article><span>01 / ${t('BEFORE · CONCEPT','ANTES · CONCEPTO')}</span><h3>${t('A more irregular surface.','Una superficie más irregular.')}</h3><p>${t('Shallow folds and a less even contour are enlarged to make the texture easier to see.','Pliegues superficiales y un contorno desigual se amplían para observar mejor la textura.')}</p></article><article><span>02 / ${t('AFTER · CONCEPT','DESPUÉS · CONCEPTO')}</span><h3>${t('A more even-looking surface.','Una superficie más uniforme.')}</h3><p>${t('A second imagined state with a smoother contour. This is a visual comparison, not a prediction of treatment response.','Un segundo estado imaginado con un contorno más liso. Es una comparación visual, no una predicción de respuesta al tratamiento.')}</p></article></div><p class="study-disclosure">${t('Stylized 3D materials, not a literal anatomical model. The ribbons and layers are visual metaphors; they do not demonstrate collagen growth, tissue repair or an effect of this mask.','Materiales 3D estilizados, no un modelo anatómico literal. Las formas y capas son metáforas visuales; no demuestran crecimiento de colágeno, reparación de tejido ni efectos de esta máscara.')}</p></div></section>`}
function productRitual(){return ''}
function productPage(){return `<section class="wrap product-page"><div class="breadcrumb"><a href="/">${t('Home','Inicio')}</a><span>/</span><span>LEZO LED Face Mask</span></div><div class="pdp-grid"><div><div class="gallery-main">${picture(pictures[selectedImage][0],t(pictures[selectedImage][1],pictures[selectedImage][2]),'',true)}<button data-zoom aria-label="${t('Enlarge product image','Ampliar imagen')}">+</button></div><div class="thumbs">${pictures.map((p,i)=>`<button data-thumb="${i}" aria-label="${t(p[1],p[2])}" aria-pressed="${selectedImage===i}">${picture(p[0],t(p[1],p[2]))}</button>`).join('')}</div><p class="editorial-caption">${t('Original product and lifestyle visualizations. Model imagery is not a testimonial.','Visualizaciones originales de producto y uso. Las modelos no representan testimonios.')}</p></div><div class="pdp-copy" id="product-buy"><span class="eyebrow">${t('THE LIGHT COLLECTION / 01','COLECCIÓN DE LUZ / 01')}</span><h1>LEZO<br>LED Face Mask.</h1><p>${t('A sculpted full-face shell with an adjustable strap that holds it in place while you sit back. Seven built-in light modes, from red to white.','Un diseño esculpido de rostro completo con correa ajustable que lo mantiene en su lugar mientras te relajas. Siete modos de luz integrados, del rojo al blanco.')}</p><div class="finish"><span></span>${t('Finish: Sculpted white · 7 modes included','Acabado: Blanco · 7 modos incluidos')}</div>${purchaseControls()}<details><summary>${t('Product details','Detalles del producto')}</summary><div class="spec-list"><div><span>${t('Format','Formato')}</span>${t('Full-face LED mask','Máscara facial LED')}</div><div><span>${t('Light modes','Modos de luz')}</span>7</div><div><span>${t('Supplier-listed channels','Canales indicados')}</span>470 / 520 / 630 nm</div><div><span>${t('Fit','Ajuste')}</span>${t('Adjustable strap','Correa ajustable')}</div></div><p>${t('Wavelengths are supplier-provided, not independently measured. Use the included manufacturer instructions for power, care and session settings.','Las longitudes de onda provienen del proveedor y no se han medido independientemente. Consulta las instrucciones incluidas para alimentación, cuidado y sesiones.')}</p></details><details><summary>${t('Returns & support','Devoluciones y ayuda')}</summary><p>${t('Request a return within 30 days of delivery. Email sevencrush.store@gmail.com with your order number before shipping your item back.','Solicita la devolución dentro de los 30 días desde la entrega. Escribe a sevencrush.store@gmail.com con tu pedido antes de enviar el artículo.')}</p></details></div></div></section>`}
function carePage(key){const p=policies[key]();return `<section class="wrap section care-page"><span class="eyebrow">SEVENCRUSH CUSTOMER CARE</span><h1>${p[0]}</h1><div class="care-grid"><div>${p.slice(1).map(x=>`<p>${x}</p>`).join('')}</div><aside><h3>${t('Need help with an order?','¿Necesitas ayuda con un pedido?')}</h3><p>${t('Include your order number so we can locate your purchase.','Incluye el número de pedido para que podamos localizar tu compra.')}</p><a class="text-link" href="mailto:${CONFIG.email}">${CONFIG.email}</a></aside></div><a class="btn" href="/products/lezo-7-color-led-face-mask">${t('Explore the mask','Explorar la máscara')} ${icon('arrow')}</a></section>`}
function render(){document.documentElement.lang=lang;const pdp=location.pathname.includes('/products/');const care=location.pathname.includes('lezo-delivery')?'shipping':location.pathname.includes('lezo-returns')?'returns':null;document.title=pdp?'LEZO LED Face Mask — Sevencrush':t('LEZO — 7-color LED face mask','LEZO — Máscara LED facial de 7 colores');document.getElementById('app').innerHTML=header()+`<main id="main">`+(care?carePage(care):pdp?productPage()+`<div style="height:55px"></div>`+trustbar()+'<div class="px-pdp-slot"></div>'+productRitual()+faq():trustbar()+'<div class="px-journey-slot"></div>'+faq())+`</main>`+footer()+`<div class="sticky-buy"><div><b>LEZO LED Mask</b><small><span class="sticky-price">${money(unitPrice())}</span> · ${t('30-day returns','Devoluciones en 30 días')}</small></div><button class="btn" data-add>${t('Add to bag','Agregar')} ${icon('arrow')}</button></div>`;setMode(selectedMode);tick();bind();updateSticky();}
function setMode(i){selectedMode=i;const m=modes[i],el=document.getElementById('mode-content');if(!el)return;el.innerHTML=`<h3 class="mode-name">${t(m.en+' light','Luz '+m.es.toLowerCase())}</h3><div class="mode-wave">${m.nm} · ${t('Supplier specification','Especificación del proveedor')}</div><span class="sheet-label">${t("Exact wording from the supplied product sheet:","Traducción del texto de la ficha del producto:")}</span><blockquote class="mode-desc">${t(m.desc[0],m.desc[1])}</blockquote>`;document.getElementById('mode-label').textContent=`0${i+1} / ${t(m.en,m.es).toUpperCase()} · ${m.nm}`;document.querySelectorAll('[data-mode]').forEach(b=>{const chosen=+b.dataset.mode===i;b.setAttribute('aria-pressed',chosen);b.querySelector('.color-state').textContent=chosen?t('Selected','Elegido'):t('Explore','Explorar')});document.querySelector('.mode-visual img').style.filter=i===6?'saturate(0) brightness(1.4)':`hue-rotate(${m.hue}deg)`;}
let previouslyActive=saleActive();
function tick(){const active=saleActive(),diff=Math.max(0,Date.parse(CONFIG.end)-Date.now()),d=Math.floor(diff/86400000),h=Math.floor(diff/3600000)%24,m=Math.floor(diff/60000)%60,s=Math.floor(diff/1000)%60;document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=active?`${d}d ${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m ${String(s).padStart(2,'0')}s`:t('Offer ended','Oferta finalizada'));document.querySelectorAll('.live-price,.sticky-price').forEach(el=>el.textContent=money(unitPrice()));document.querySelectorAll('.sale-only').forEach(el=>el.hidden=!active);if(previouslyActive!==active){previouslyActive=active;document.querySelector('[data-promo]').textContent=t('LEZO · AT-HOME LED SKINCARE','LEZO · CUIDADO LED EN CASA');if(document.getElementById('cart').open)renderCart();}}
function setQty(n){qty=Math.max(1,Math.min(20,parseInt(n,10)||1));document.querySelectorAll('.product-qty').forEach(x=>x.value=qty)}
function checkout(q){const amount=Math.max(1,Math.min(20,q));const url=new URL(`${CONFIG.store}/cart/${CONFIG.variant}:${amount}`);if(saleActive())url.searchParams.set('discount',CONFIG.code);url.searchParams.set('locale',lang);window.location.assign(url.href)}
function updateCart(){save('lezo-cart',String(cartQty));document.querySelectorAll('.cart-count').forEach(e=>e.textContent=cartQty)}
function renderCart(){const el=document.getElementById('cart');el.innerHTML=`<button class="close" data-close aria-label="${t('Close bag','Cerrar carrito')}">×</button><span class="eyebrow">LEZO BY SEVENCRUSH</span><h2 id="cart-title">${t('Your bag.','Tu carrito.')}</h2>`+(cartQty?`<div class="cart-item">${picture(location.pathname.includes('/products/')?'pdp-front':'hero',t('LEZO LED mask','Máscara LED LEZO'))}<div><h3>LEZO LED Mask</h3><p style="margin:4px 0;font-size:11px">${t('White · 7 light modes','Blanca · 7 modos de luz')}</p><div class="quantity"><button data-cart-qty="-1" aria-label="${t('Decrease quantity','Reducir cantidad')}">−</button><span style="width:25px;text-align:center">${cartQty}</span><button data-cart-qty="1" aria-label="${t('Increase quantity','Aumentar cantidad')}" ${cartQty>=20?'disabled':''}>+</button></div><button class="remove" data-remove>${t('Remove','Eliminar')}</button></div></div><div class="cart-summary"><div><span>${t('Original subtotal','Subtotal original')}</span><span>${money(CONFIG.regular*cartQty)}</span></div>${saleActive()?`<div class="discount"><span>LEZO45 · 45% OFF</span><span>−${money((CONFIG.regular-CONFIG.sale)*cartQty)}</span></div>`:''}<div class="total"><span>${t('Subtotal','Subtotal')}</span><span>${money(unitPrice()*cartQty)}</span></div><p class="small">${t('Estimated delivery: 5–12 days. Shipping and taxes are calculated at checkout.','Entrega estimada: de 5 a 12 días. El envío e impuestos se calculan al pagar.')}</p></div><button class="btn checkout" id="checkout">${icon('shield')}${t('Secure checkout','Pagar de forma segura')}${icon('arrow')}</button><p class="small">${t('30-day returns. Payment methods and final totals are shown before you pay.','Devoluciones en 30 días. Los métodos de pago y total final se muestran antes de pagar.')}</p><button class="text-link" data-close>${t('Continue exploring','Seguir explorando')}</button>`:`<div class="empty-cart"><p>${t('Your bag is empty. Explore the seven-color LED mask to get started.','Tu carrito está vacío. Explora la máscara LED de siete colores para empezar.')}</p><a class="btn" href="/products/lezo-7-color-led-face-mask">${t('Buy LEZO','Comprar LEZO')}${icon('arrow')}</a></div>`);el.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>el.close());el.querySelectorAll('[data-cart-qty]').forEach(b=>b.onclick=()=>{cartQty=Math.max(0,Math.min(20,cartQty+Number(b.dataset.cartQty)));updateCart();renderCart()});el.querySelector('[data-remove]')?.addEventListener('click',()=>{cartQty=0;updateCart();renderCart()});el.querySelector('#checkout')?.addEventListener('click',()=>checkout(cartQty));}
function openCart(){renderCart();document.getElementById('cart').showModal()}
function add(){cartQty=Math.min(20,cartQty+qty);updateCart();openCart()}
const policies={returns:()=>[t('30-day returns.','Devoluciones en 30 días.'),t('You may request a return for your LEZO mask within 30 days of delivery. Email sevencrush.store@gmail.com with your order number and the reason for your request.','Puedes solicitar la devolución de tu máscara LEZO dentro de los 30 días desde la entrega. Envía un correo a sevencrush.store@gmail.com con tu número de pedido y el motivo.'),t('Please contact us before shipping anything back. We will provide the return address and instructions, including any applicable return-shipping cost. Include the mask and the accessories supplied with your order.','Contáctanos antes de enviar el artículo. Te daremos la dirección e instrucciones, incluido cualquier costo de envío de devolución aplicable. Incluye la máscara y los accesorios recibidos.'),t('For an item that arrived damaged, defective or incorrect, include photos with your request so we can help resolve it. Approved refunds are returned to the original payment method; processing time depends on your payment provider.','Si el artículo llegó dañado, defectuoso o equivocado, incluye fotos para ayudarnos a resolverlo. Los reembolsos aprobados se devuelven al método de pago original; el tiempo depende del proveedor de pago.')],shipping:()=>[t('Shipping & delivery.','Envío y entrega.'),t('Estimated delivery is 5–12 days. This is an estimate, not a guaranteed arrival date. Shipping charges and taxes are calculated at checkout for your destination.','La entrega estimada es de 5 a 12 días. Es un plazo orientativo, no una fecha de llegada garantizada. Los gastos de envío e impuestos se calculan al pagar según tu destino.'),t('Updates about your order are sent to the email address entered at checkout. If tracking is available, you will receive the tracking details with your shipping confirmation. For order support, email sevencrush.store@gmail.com with your order number.','Las actualizaciones se envían al correo indicado al pagar. Si hay seguimiento disponible, recibirás esos datos con la confirmación de envío. Escribe a sevencrush.store@gmail.com con tu número de pedido para recibir ayuda.')],privacy:()=>[t('Your privacy.','Tu privacidad.'),t('This storefront stores your language choice and bag quantity in your browser so they remain available on your next visit. This page does not collect payment-card details.','Esta tienda guarda tu idioma y la cantidad del carrito en tu navegador para mantenerlos en tu próxima visita. Esta página no recopila datos de tarjetas.'),t('When you check out, Shopify and Sevencrush process the information needed to fulfill your order, including your contact, delivery and payment information. The store’s checkout privacy policy applies. If you contact us by email, we use the information you send to respond to your request.','Al pagar, Shopify y Sevencrush procesan la información necesaria para tu pedido, incluidos contacto, entrega y pago. Aplica la política de privacidad del checkout. Si nos escribes, utilizamos la información enviada para responder a tu solicitud.'),`<a class="text-link" href="${CONFIG.store}/policies/privacy-policy" target="_blank" rel="noopener">${t('Read Sevencrush’s privacy policy ↗','Leer política de privacidad de Sevencrush ↗')}</a>`],terms:()=>[t('Shopping terms.','Términos de compra.'),t('Prices are listed in US dollars. Shipping and tax are calculated at checkout. The LEZO45 promotion gives 45% off the $119 regular price of this mask, from October 24 through October 31, 2026 at 4:31 p.m. Eastern Time. The discount is limited to this product and may not combine with other promotions.','Los precios están en dólares estadounidenses. Envío e impuestos se calculan al pagar. LEZO45 ofrece 45% sobre el precio regular de $119 de esta máscara, del 24 al 31 de octubre de 2026 a las 4:31 p. m., hora del este. El descuento se limita a este producto y puede no combinarse con otras promociones.'),t('Product images are original editorial visualizations. Light colors are approximate. Supplier-listed wavelengths and benefits have not been independently verified for this model. No clinical result, treatment outcome or FDA clearance is promised. Always follow the supplied use and safety instructions.','Las imágenes son visualizaciones editoriales originales. Los colores de luz son aproximados. Las longitudes de onda y beneficios indicados por el proveedor no han sido verificados independientemente para este modelo. No se prometen resultados clínicos, curación ni autorización FDA. Sigue las instrucciones de uso y seguridad incluidas.'),`<a class="text-link" href="${CONFIG.store}/policies/terms-of-service" target="_blank" rel="noopener">${t('Read Sevencrush’s store terms ↗','Leer términos de Sevencrush ↗')}</a>`]};
function showPolicy(key){const contents=policies[key]();const el=document.getElementById('policy');el.innerHTML=`<button class="close" aria-label="${t('Close','Cerrar')}">×</button><span class="eyebrow">SEVENCRUSH CUSTOMER CARE</span><h2 id="policy-title">${contents[0]}</h2>${contents.slice(1).map(p=>`<p>${p}</p>`).join('')}`;el.querySelector('.close').onclick=()=>el.close();el.showModal()}
function bind(){document.querySelectorAll('[data-compare]').forEach(input=>input.oninput=()=>{input.closest('.skin-comparison').style.setProperty('--split',input.value+'%');input.setAttribute('aria-valuetext',input.value+'%')});document.getElementById('language').onclick=()=>{const y=scrollY;lang=lang==='en'?'es':'en';save('lezo-language',lang);render();scrollTo(0,y)};document.getElementById('menu').onclick=(e)=>{const menu=document.querySelector('.mobile-nav');const open=menu.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)};document.querySelectorAll('.mobile-nav a').forEach(a=>a.onclick=()=>{document.querySelector('.mobile-nav').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false')});document.querySelectorAll('[data-cart]').forEach(b=>b.onclick=openCart);document.querySelectorAll('[data-add]').forEach(b=>b.onclick=add);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>checkout(qty));document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>setQty(qty+Number(b.dataset.qty)));document.querySelectorAll('.product-qty').forEach(el=>el.onchange=()=>setQty(el.value));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(Number(b.dataset.mode)));document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>showPolicy(b.dataset.policy));document.querySelectorAll('[data-thumb]').forEach(b=>b.onclick=()=>{selectedImage=Number(b.dataset.thumb);const img=document.querySelector('.gallery-main img');img.src=asset(pictures[selectedImage][0]);img.alt=t(pictures[selectedImage][1],pictures[selectedImage][2]);document.querySelectorAll('[data-thumb]').forEach(x=>x.setAttribute('aria-pressed',x===b))});document.querySelector('[data-zoom]')?.addEventListener('click',()=>{const dialog=document.getElementById('zoom');dialog.querySelector('img').src=asset(pictures[selectedImage][0]);dialog.querySelector('img').alt=t(pictures[selectedImage][1],pictures[selectedImage][2]);dialog.showModal()})}
function updateSticky(){document.querySelector('.sticky-buy')?.classList.toggle('visible',scrollY>700)}
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
addEventListener('scroll',updateSticky,{passive:true});


let nativeCart=window.LEZO_SHOPIFY.cart;
let cartBusy=false;
cartQty=nativeCart.item_count;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cartRoot=window.Shopify?.routes?.root||'/';
const lineSaving=item=>saleActive()&&String(item.variant_id)===CONFIG.variant?Math.max(0,item.final_line_price/100-CONFIG.sale*item.quantity):0;
async function cartRequest(path,body){const response=await fetch(cartRoot+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','Accept':'application/json'},credentials:'same-origin',body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.description||data.message||t('Unable to update your bag. Please try again.','No se pudo actualizar el carrito. Inténtalo de nuevo.'));return data;}
function updateCart(){cartQty=nativeCart.item_count;document.querySelectorAll('.cart-count').forEach(e=>e.textContent=cartQty);}
function cartMessage(message){const d=document.getElementById('cart');let p=d.querySelector('.cart-status');if(!p){p=document.createElement('p');p.className='cart-status';p.setAttribute('role','status');d.append(p)}p.textContent=message;}
async function changeLine(key,quantity){if(cartBusy)return;cartBusy=true;const d=document.getElementById('cart');d.setAttribute('aria-busy','true');try{nativeCart=await cartRequest('cart/change.js',{id:key,quantity});updateCart();renderCart();}catch(e){cartMessage(e.message)}finally{cartBusy=false;d.removeAttribute('aria-busy');}}
function renderCart(){const d=document.getElementById('cart');const savings=nativeCart.items.reduce((s,i)=>s+lineSaving(i),0);const total=nativeCart.total_price/100-savings;const discount=Math.max(0,nativeCart.original_total_price/100-total);d.innerHTML=`<button class="close" data-close aria-label="${t('Close bag','Cerrar carrito')}">×</button><span class="eyebrow">LEZO BY SEVENCRUSH</span><h2 id="cart-title">${t('Your bag.','Tu carrito.')}</h2>`+(nativeCart.item_count?nativeCart.items.map(item=>`<div class="cart-item"><img src="${esc(item.featured_image?.url||item.image||asset('pdp-front'))}" alt="${esc(item.product_title)}" width="120" height="120"><div><h3>${esc(item.product_title)}</h3><p class="small">${money(item.final_line_price/100-lineSaving(item))}</p><div class="quantity"><button data-key="${esc(item.key)}" data-next="${item.quantity-1}" aria-label="${t('Decrease quantity','Reducir cantidad')}">−</button><span>${item.quantity}</span><button data-key="${esc(item.key)}" data-next="${item.quantity+1}" aria-label="${t('Increase quantity','Aumentar cantidad')}" ${item.quantity>=20?'disabled':''}>+</button></div><button class="remove" data-key="${esc(item.key)}" data-next="0">${t('Remove','Eliminar')}</button></div></div>`).join('')+`<div class="cart-summary"><div><span>${t('Original subtotal','Subtotal original')}</span><span>${money(nativeCart.original_total_price/100)}</span></div>${discount?`<div class="discount"><span>${t('Discounts','Descuentos')}</span><span>−${money(discount)}</span></div>`:''}<div class="total"><span>${t('Estimated subtotal','Subtotal estimado')}</span><span>${money(nativeCart.total_price/100-savings)}</span></div><p class="small">${t('Estimated delivery: 5–12 days. Shipping and taxes calculated at checkout.','Entrega estimada: de 5 a 12 días. Envío e impuestos calculados al pagar.')}</p></div><button class="btn checkout" id="checkout">${icon('shield')}${t('Secure checkout','Pago seguro')}${icon('arrow')}</button><p class="small">${t('30-day returns. The final price and applicable discounts are confirmed at checkout.','Devoluciones en 30 días. El precio final y los descuentos aplicables se confirman al pagar.')}</p>`:`<div class="empty-cart"><p>${t('Your bag is empty.','Tu carrito está vacío.')}</p><a class="btn" href="/products/lezo-7-color-led-face-mask">${t('Explore the mask','Explorar la máscara')}</a></div>`);d.querySelector('[data-close]').onclick=()=>d.close();d.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>changeLine(b.dataset.key,Number(b.dataset.next)));d.querySelector('#checkout')?.addEventListener('click',goToCheckout);}
function openCart(){renderCart();const d=document.getElementById('cart');if(!d.open)d.showModal();cartRequest('cart.js').then(c=>{nativeCart=c;updateCart();if(d.open)renderCart()}).catch(()=>cartMessage(t('Connection interrupted. Try again to refresh your bag.','Conexión interrumpida. Inténtalo de nuevo para actualizar el carrito.')));}
async function addNative(quantity,go){if(cartBusy)return;cartBusy=true;document.querySelectorAll('[data-add],[data-buy]').forEach(b=>b.disabled=true);try{await cartRequest('cart/add.js',{items:[{id:Number(CONFIG.variant),quantity}]});nativeCart=await cartRequest('cart.js');updateCart();if(go){goToCheckout()}else{renderCart();document.getElementById('cart').showModal()}}catch(e){renderCart();const d=document.getElementById('cart');if(!d.open)d.showModal();cartMessage(e.message)}finally{cartBusy=false;document.querySelectorAll('[data-add],[data-buy]').forEach(b=>b.disabled=!window.LEZO_SHOPIFY.available);}}
function add(){return addNative(qty,false)}
function checkout(q){return addNative(q,true)}
function goToCheckout(){location.assign(saleActive()?'/discount/'+encodeURIComponent(CONFIG.code)+'?redirect=/checkout':'/checkout');}

render();setInterval(tick,1000);if(!window.LEZO_SHOPIFY.available){document.querySelectorAll('[data-add],[data-buy]').forEach(b=>{b.disabled=true;b.textContent=t('Currently unavailable','No disponible')})}if(location.pathname==='/cart')openCart();
